class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        best = float('inf')
        def dfs(i, pl, pr, acc):
            nonlocal best
            if acc >= best:
                return
            if i == n // 2:
                best = acc
                return
            for c in range(3):
                for d in range(3):
                    if c != d and c != pl and d != pr:
                        dfs(i + 1, c, d, acc + cost[i][c] + cost[n - 1 - i][d])
        dfs(0, -1, -1, 0)
        return best

