class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        dp = [[INF] * 3 for _ in range(3)]
        for c in range(3):
            for d in range(3):
                if c != d:
                    dp[c][d] = cost[0][c] + cost[n - 1][d]
        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            for c in range(3):
                for d in range(3):
                    if c == d:
                        continue
                    base = cost[i][c] + cost[n - 1 - i][d]
                    for pc in range(3):
                        if pc == c:
                            continue
                        row = dp[pc]
                        for pd in range(3):
                            if pd != d and row[pd] + base < ndp[c][d]:
                                ndp[c][d] = row[pd] + base
            dp = ndp
        return min(min(r) for r in dp)

