class Solution {
public:
    long long minCost(int n, vector<vector<int>>& cost) {
        const long long INF = LLONG_MAX / 2;
        vector<vector<long long>> dp(3, vector<long long>(3, INF));
        for (int c = 0; c < 3; c++)
            for (int d = 0; d < 3; d++)
                if (c != d) dp[c][d] = cost[0][c] + cost[n - 1][d];
        for (int i = 1; i < n / 2; i++) {
            vector<vector<long long>> ndp(3, vector<long long>(3, INF));
            for (int c = 0; c < 3; c++)
                for (int d = 0; d < 3; d++) {
                    if (c == d) continue;
                    long long base = cost[i][c] + cost[n - 1 - i][d];
                    for (int pc = 0; pc < 3; pc++) {
                        if (pc == c) continue;
                        for (int pd = 0; pd < 3; pd++)
                            if (pd != d)
                                ndp[c][d] = min(ndp[c][d], dp[pc][pd] + base);
                    }
                }
            dp = move(ndp);
        }
        long long ans = INF;
        for (auto& r : dp) for (long long v : r) ans = min(ans, v);
        return ans;
    }
};

