class Solution {
    public long minCost(int n, int[][] cost) {
        final long INF = Long.MAX_VALUE / 2;
        long[][] dp = new long[3][3];
        for (int c = 0; c < 3; c++)
            for (int d = 0; d < 3; d++)
                dp[c][d] = (c == d) ? INF : cost[0][c] + cost[n - 1][d];
        for (int i = 1; i < n / 2; i++) {
            long[][] ndp = new long[3][3];
            for (long[] r : ndp) Arrays.fill(r, INF);
            for (int c = 0; c < 3; c++)
                for (int d = 0; d < 3; d++) {
                    if (c == d) continue;
                    long base = cost[i][c] + cost[n - 1 - i][d];
                    for (int pc = 0; pc < 3; pc++) {
                        if (pc == c) continue;
                        for (int pd = 0; pd < 3; pd++)
                            if (pd != d)
                                ndp[c][d] = Math.min(ndp[c][d], dp[pc][pd] + base);
                    }
                }
            dp = ndp;
        }
        long ans = INF;
        for (long[] r : dp) for (long v : r) ans = Math.min(ans, v);
        return ans;
    }
}

