var minCost = function(n, cost) {
    const INF = Infinity;
    let dp = Array.from({length: 3}, () => Array(3).fill(INF));
    for (let c = 0; c < 3; c++)
        for (let d = 0; d < 3; d++)
            if (c !== d) dp[c][d] = cost[0][c] + cost[n - 1][d];
    for (let i = 1; i < n / 2; i++) {
        const ndp = Array.from({length: 3}, () => Array(3).fill(INF));
        for (let c = 0; c < 3; c++)
            for (let d = 0; d < 3; d++) {
                if (c === d) continue;
                const base = cost[i][c] + cost[n - 1 - i][d];
                for (let pc = 0; pc < 3; pc++) {
                    if (pc === c) continue;
                    for (let pd = 0; pd < 3; pd++)
                        if (pd !== d && dp[pc][pd] + base < ndp[c][d])
                            ndp[c][d] = dp[pc][pd] + base;
                }
            }
        dp = ndp;
    }
    return Math.min(...dp.flat());
};
